<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount,nextTick} from 'vue';import {IconX,IconArrowRight,IconVolume,IconDownload} from '@tabler/icons-vue';import {modal,draft,studio,loadStudio,show,saveParameters} from './state';import {api,health,error,notify,current,refresh,select} from '../store';import SealViewer from '../components/SealViewer.vue';import Art from './Art.vue'
const nickname=ref(''),bio=ref(''),reconstructing=ref(false),modelError=ref('')
const m=computed(()=>modal.value)
let trigger:HTMLElement|null=null
watch(m,async(value,previous)=>{nickname.value=studio.value.profile.name;bio.value=studio.value.profile.bio;modelError.value='';if(value){if(!previous)trigger=document.activeElement as HTMLElement;await nextTick();document.querySelector<HTMLElement>('.im-dialog input:not([type=color]),.im-dialog button')?.focus()}else trigger?.focus()})
function close(){modal.value=null;window.speechSynthesis?.cancel()}
function key(e:KeyboardEvent){if(!m.value)return;if(e.key==='Escape')close();if(e.key==='Tab'){const nodes=Array.from(document.querySelectorAll<HTMLElement>('.im-dialog button:not(:disabled),.im-dialog a[href],.im-dialog input,.im-dialog textarea,.im-dialog select')).filter(x=>x.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}
window.addEventListener('keydown',key);onBeforeUnmount(()=>window.removeEventListener('keydown',key))
async function profile(){try{await api('/studio/profile',{method:'PATCH',body:JSON.stringify({name:nickname.value,bio:bio.value})});await loadStudio();close();notify('个人资料已保存到MySQL')}catch(e){error.value=String(e)}}
function speak(){if(!('speechSynthesis'in window)){notify('当前设备不支持浏览器语音');return}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(m.value?.data?.text||'印脉重生，以印为媒，连接传统与未来。');utterance.lang='zh-CN';speechSynthesis.speak(utterance)}
async function mesh(){if(!current.value){modelError.value='请先上传真实印谱，再选择要处理的图像。';return}reconstructing.value=true;try{await api('/seals/'+current.value.id+'/reconstruct',{method:'POST',body:JSON.stringify({width_mm:30,base_mm:3,relief_mm:1.2,resolution:96,style:draft.value.polarity,mirror:true})});await refresh();modal.value={kind:'mesh',title:'真实三维印面',data:{url:current.value?.artifacts.filter(a=>a.kind==='stl').at(-1)?.url}}}catch(e){modelError.value=e instanceof Error?e.message:String(e)}finally{reconstructing.value=false}}
function saveImage(){const a=document.createElement('a');a.href=m.value?.data?.image;a.download='视觉参考.png';a.click()}
</script>
<template>
<div v-if="m" class="im-dialog-backdrop" @click.self="close"><section class="im-dialog" :class="{'im-dialog-wide':['image','mesh','compare','map'].includes(m.kind)}" role="dialog" aria-modal="true" :aria-label="m.title"><header><h2>{{m.title}}</h2><button autofocus aria-label="关闭对话框" @click="close"><IconX :size="23"/></button></header>
<div v-if="m.kind==='profile'"><label>昵称<input v-model="nickname" maxlength="40" aria-label="昵称"></label><label>个人简介<textarea v-model="bio" maxlength="200" aria-label="个人简介"/></label><button class="im-gold-button" @click="profile">保存个人资料</button><p class="im-note">当前是本机单用户工作区，未接入账户登录或付费会员。</p></div>
<div v-else-if="m.kind==='image'||m.kind==='map'"><img class="im-dialog-image" :src="m.data?.image" :alt="m.title"><p class="im-note">{{m.data?.actual?'实际规范字排版输出，已保存到本机数据库；未应用篆刻风格模型。':'用户提供的视觉参考素材，非新生成的AI结果或已核实文物影像。'}}</p></div>
<div v-else-if="m.kind==='mesh'"><div class="im-modal-model"><SealViewer :url="m.data?.url"/></div><p>真实模型采用二维印文生成封闭的印面浮雕；支持旋转、缩放与导出。狮钮、云龙雕塑仍为视觉参考。</p><p v-if="modelError" role="alert">{{modelError}}</p><div class="im-dialog-actions"><a v-if="m.data?.url" class="im-gold-button" :href="m.data.url" download><IconDownload :size="18"/> 下载STL</a><button v-else class="im-gold-button" :disabled="reconstructing" @click="mesh">{{reconstructing?'正在生成…':'从当前实际作品生成STL'}}</button><RouterLink to="/reconstruction" @click="close">完整三维工作台</RouterLink></div></div>
<div v-else-if="m.kind==='status'"><p>数据库：{{health?'已连接 MySQL':'连接检查中或不可用'}}。本机单用户工作区。</p><ul><li>可运行：上传、图像预处理、人工标注、自动分割、收藏、方案保存、规范字排版、封闭STL印面。</li><li>实验功能：去噪模型与字形训练。训练材料尚未形成审核通过的字形配对数据。</li><li>未完成：古印文自动释读、指定篆刻风格生成、缺笔AI修复、狮钮自动建模。</li><li>未接入：支付、公开发布、完整AR/VR、HarmonyOS设备验证。</li></ul><RouterLink to="/workspace" @click="close">打开处理工作台</RouterLink></div>
<div v-else-if="m.kind==='advanced'"><label>印面方式<select v-model="draft.polarity"><option value="zhu">朱文 · 凸字</option><option value="bai">白文 · 凹字</option></select></label><label>排版<select v-model="draft.layout"><option value="square">方阵</option><option value="vertical">竖排</option><option value="horizontal">横排</option></select></label><label>印泥颜色<input type="color" v-model="draft.ink"></label><p>选择会保存到方案。刀痕、纹样、金属工艺目前仅记录设计意向，尚未应用于实际模型。</p><button class="im-gold-button" @click="saveParameters()">保存参数方案</button></div>
<div v-else-if="m.kind==='history'"><div class="im-history-list" v-if="studio.designs.length"><button v-for="d in studio.designs" @click="d.seal_id&&(select(d.seal_id),$router.push('/reconstruction'),close())"><b>{{d.title}}</b><span>{{d.source_kind==='native_typeset'?'规范字排版':'参数草案'}}</span><time>{{d.created_at}}</time></button></div><p v-else>还没有实际创作记录。上传印谱或保存方案后，这里会显示真实记录。</p></div>
<div v-else-if="m.kind==='design'"><pre>{{JSON.stringify(m.data?.design?.parameters,null,2)}}</pre></div>
<div v-else-if="m.kind==='exports'"><p>仅列出实际入库文件。图片、模型与处理结果可直接下载。</p><article v-for="s in m.data?.seals"><h3>{{s.title}}</h3><div class="im-export-list"><a v-for="a in s.artifacts" :href="a.url" download>{{a.kind}} <IconDownload :size="16"/></a></div></article><p v-if="!m.data?.seals.length">还没有实际文件。</p></div><div v-else-if="m.kind==='export'"><p>{{m.data?.seal?.title}} · 实际入库文件</p><div class="im-export-list"><a v-for="a in m.data?.seal?.artifacts" :href="a.url" download>{{a.kind}} <IconDownload :size="18"/></a></div><RouterLink to="/reconstruction" @click="close">生成新的三维印面</RouterLink></div>
<div v-else-if="m.kind==='download'"><img class="im-dialog-image" :src="m.data?.image" :alt="m.title"><p>此图片是用户提供的UI视觉参考，可下载参考裁图；没有对应的真实STL。</p><button class="im-gold-button" @click="saveImage">下载视觉参考图片</button></div>
<div v-else-if="m.kind==='share'"><p>本机链接</p><input readonly :value="m.data?.url" aria-label="分享链接"></div>
<div v-else-if="m.kind==='speech'"><p>{{m.data?.text||'印脉重生，以印为媒，连接传统与未来。'}}</p><button class="im-gold-button" @click="speak"><IconVolume :size="18"/> 使用设备语音朗读</button><p class="im-note">使用浏览器语音合成；不是云端AI讲解。</p></div>
<div v-else-if="m.kind==='compare'" class="im-comparison"><figure v-for="i in 4"><Art :name="'scheme-'+(i-1)" :alt="'参考方案'+i"/><figcaption>参考方案 {{i}} · 非本次AI生成</figcaption></figure></div>
<div v-else-if="m.kind==='scheme'"><Art class="im-dialog-image" :name="'scheme-'+(m.data?.index||0)" alt="方案视觉参考"/><p>这是参考图中的方案示例。可以保存当前所选参数，或进入定制继续设计。</p><div class="im-dialog-actions"><button class="im-gold-button" @click="saveParameters()">保存所选参数</button><RouterLink to="/customize" @click="close">进入个性定制</RouterLink></div></div>
<div v-else-if="m.kind==='knowledge'"><p>{{m.data?.notice}}</p><article v-for="r in (Array.isArray(m.data?.rows)?m.data.rows:m.data?.rows?.items||[])" class="im-knowledge-result"><h3>{{r.title}}</h3><p>{{r.content||r.summary}}</p><small>{{r.source}}</small></article><RouterLink to="/knowledge" @click="close">打开有来源的知识库</RouterLink></div>
<div v-else-if="m.kind==='account-feature'"><p>此区保留参考图中的视觉入口。当前没有接入{{m.title.includes('会员')?'付费会员':m.title.includes('订单')?'支付或实体订单':'公开发布服务'}}，图示数字与状态只在“视觉示例”模式中展示。</p><p>可用功能：本机作品、收藏、参数方案、实际图片与STL文件导出。</p><button class="im-gold-button" @click="close">返回作品管理</button></div>
<div v-else-if="m.kind==='experience'"><p>{{m.data?.index===0?'完整AR需要设备摄像头、定位与模型跟踪，目前尚未接入。':'参考场景尚未制作成可漫游的三维模型。'}}当前可查看实际生成的三维印面，支持真实旋转、缩放与STL导出。</p><button class="im-gold-button" @click="show('mesh','数字展柜 · 真实模型',{url:current?.artifacts.filter(a=>a.kind==='stl').at(-1)?.url})">打开真实三维展柜</button></div>
<div v-else-if="m.kind==='stories'||m.kind==='timeline'"><p>这些画面展示参考图里的文化叙事。项目已收录的文献与出处可在知识库查看；未经核验的图示故事不作为史实结论。</p><RouterLink to="/knowledge" @click="close">查看带来源的资料</RouterLink></div>
<div v-else><p>当前展示的是用户提供的视觉参考。篆刻风格、钮饰、复杂纹样与石材雕塑尚未接入生成模型；可以保存设计参数，继续准备经过人工审核的训练字形。真实输出目前支持规范字排版、图像处理和可制造的三维印面。</p><div class="im-dialog-actions"><RouterLink to="/font" @click="close">字形训练与标注</RouterLink><RouterLink to="/reconstruction" @click="close">真实三维工作台</RouterLink></div></div>
</section></div>
</template>
